**What this code covers**

- syntax = "proto3"; package usersvc;
- Mock gRPC service definition + stub client in pure stdlib.
- Mimics the .proto -> generated code -> server + client flow
- Without requiring the grpcio package, so the demo runs anywhere.
- .proto definition (what a developer writes)
- "Generated" message classes (what protoc produces)
- Tiny "protobuf-like" encoding: field_tag + varint.
- GRPC server (mock HTTP/2 framing over TCP)

**Defines:** `GetUserRequest`, `User`, `UploadSummary`, `_encode_varint()`, `_decode_varint()`, `GRPCServer`, `_ListUsersRequestDeserialize()`, `UserServiceServicer`, `UserServiceStub`, `_recvn()`

```python
# Mock gRPC service definition + stub client in pure stdlib.
# Mimics the .proto -> generated code -> server + client flow
# without requiring the grpcio package, so the demo runs anywhere.

import socket
import threading
import struct
import json
import time
from dataclasses import dataclass, field
from typing import Optional, Callable

# --- .proto definition (what a developer writes) -----------------

PROTO = '''
syntax = "proto3";
package usersvc;

service UserService {
  rpc GetUser(GetUserRequest) returns (User);
  rpc ListUsers(ListUsersRequest) returns (stream User);
  rpc UploadUsers(stream User) returns (UploadSummary);
}

message GetUserRequest { int64 id = 1; }
message ListUsersRequest { int32 limit = 1; }
message User { int64 id = 1; string name = 2; string email = 3; }
message UploadSummary { int32 count = 1; }
'''

# --- "Generated" message classes (what protoc produces) ----------

@dataclass
class GetUserRequest:
    id: int = 0

    def serialize(self) -> bytes:
        # Tiny "protobuf-like" encoding: field_tag + varint.
        out = bytearray()
        if self.id != 0:
            out.append(0x08)  # tag: field 1, wire type 0 (varint)
            out.extend(_encode_varint(self.id))
        return bytes(out)

    @classmethod
    def deserialize(cls, data: bytes) -> "GetUserRequest":
        req = cls()
        i = 0
        while i < len(data):
            tag = data[i]; i += 1
            field_no = tag >> 3
            if field_no == 1:
                val, i = _decode_varint(data, i)
                req.id = val
        return req

@dataclass
class User:
    id: int = 0
    name: str = ""
    email: str = ""

    def serialize(self) -> bytes:
        out = bytearray()
        if self.id != 0:
            out.append(0x08); out.extend(_encode_varint(self.id))
        if self.name:
            b = self.name.encode()
            out.append(0x12); out.extend(_encode_varint(len(b))); out.extend(b)
        if self.email:
            b = self.email.encode()
            out.append(0x1a); out.extend(_encode_varint(len(b))); out.extend(b)
        return bytes(out)

    @classmethod
    def deserialize(cls, data: bytes) -> "User":
        u = cls()
        i = 0
        while i < len(data):
            tag = data[i]; i += 1
            field_no = tag >> 3
            if field_no == 1:
                u.id, i = _decode_varint(data, i)
            elif field_no == 2:
                ln, i = _decode_varint(data, i)
                u.name = data[i:i + ln].decode(); i += ln
            elif field_no == 3:
                ln, i = _decode_varint(data, i)
                u.email = data[i:i + ln].decode(); i += ln
        return u

@dataclass
class UploadSummary:
    count: int = 0

    def serialize(self) -> bytes:
        out = bytearray()
        if self.count != 0:
            out.append(0x08); out.extend(_encode_varint(self.count))
        return bytes(out)

    @classmethod
    def deserialize(cls, data: bytes) -> "UploadSummary":
        s = cls()
        i = 0
        while i < len(data):
            tag = data[i]; i += 1
            if (tag >> 3) == 1:
                s.count, i = _decode_varint(data, i)
        return s

def _encode_varint(n: int) -> bytes:
    out = bytearray()
    while n > 0x7F:
        out.append((n & 0x7F) | 0x80)
        n >>= 7
    out.append(n & 0x7F)
    return bytes(out)

def _decode_varint(data: bytes, i: int) -> tuple:
    result = 0
    shift = 0
    while True:
        b = data[i]; i += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            break
        shift += 7
    return result, i

# --- gRPC server (mock HTTP/2 framing over TCP) ------------------

@dataclass
class GRPCServer:
    host: str
    port: int
    handlers: dict = field(default_factory=dict)
    _sock: Optional[socket.socket] = None

    def add_servicer(self, servicer):
        # Register Unary handler: GetUser
        self.handlers["/usersvc.UserService/GetUser"] = (
            lambda req_data: servicer.GetUser(
                GetUserRequest.deserialize(req_data)).serialize())
        # Server streaming: ListUsers
        def list_users_handler(req_data):
            req = _ListUsersRequestDeserialize(req_data)
            for u in servicer.ListUsers(req):
                yield u.serialize()
        self.handlers["/usersvc.UserService/ListUsers"] = list_users_handler
        # Client streaming: UploadUsers
        def upload_users_handler(req_stream):
            count = servicer.UploadUsers(req_stream)
            return UploadSummary(count=count).serialize()
        self.handlers["/usersvc.UserService/UploadUsers"] = upload_users_handler

    def serve(self):
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._sock.bind((self.host, self.port))
        self._sock.listen(8)
        while True:
            conn, _ = self._sock.accept()
            threading.Thread(target=self._handle, args=(conn,),
                             daemon=True).start()

    def _handle(self, conn):
        try:
            while True:
                # Read framing: 1 byte compressed flag + 4 byte length + msg.
                header = self._recvn(conn, 5)
                if not header:
                    break
                compressed = header[0]
                length = struct.unpack(">I", header[1:5])[0]
                path_bytes = self._recvn(conn, 64)
                path = path_bytes.rstrip(b"\x00").decode()
                req_data = self._recvn(conn, length)
                handler = self.handlers.get(path)
                if handler is None:
                    conn.sendall(b"\x00" + struct.pack(">I", 0))
                    continue
                # Check if it's a generator (server streaming).
                result = handler(req_data)
                if hasattr(result, "__iter__") and not isinstance(
                        result, (bytes, bytearray)):
                    for msg in result:
                        conn.sendall(b"\x01" + struct.pack(">I", len(msg))
                                     + msg)
                    conn.sendall(b"\x02" + struct.pack(">I", 0))  # EOS
                else:
                    conn.sendall(b"\x00" + struct.pack(">I", len(result))
                                 + result)
        except (ConnectionResetError, OSError):
            pass
        finally:
            conn.close()

    @staticmethod
    def _recvn(conn, n: int) -> bytes:
        out = b""
        while len(out) < n:
            chunk = conn.recv(n - len(out))
            if not chunk:
                return out
            out += chunk
        return out

def _ListUsersRequestDeserialize(data: bytes) -> "ListUsersRequest":
    # Trivial: returns an object with .limit field.
    class ListUsersRequest:
        def __init__(self):
            self.limit = 10
    return ListUsersRequest()

# --- Server implementation (what the developer writes) -----------

class UserServiceServicer:
    def __init__(self):
        self.users = {
            1: User(id=1, name="Ada Lovelace", email="ada@example.com"),
            2: User(id=2, name="Grace Hopper", email="grace@example.com"),
            3: User(id=3, name="Alan Turing", email="alan@example.com"),
        }

    def GetUser(self, request: GetUserRequest) -> User:
        return self.users.get(request.id, User(id=0, name="not found"))

    def ListUsers(self, request):
        for u in self.users.values():
            yield u  # server streaming: yield each User one at a time

    def UploadUsers(self, req_stream) -> int:
        count = 0
        for raw in req_stream:
            u = User.deserialize(raw)
            self.users[u.id] = u
            count += 1
        return count

# --- gRPC client stub (what protoc generates) --------------------

@dataclass
class UserServiceStub:
    channel: tuple  # (host, port)

    def GetUser(self, request: GetUserRequest,
                timeout: float = 5.0) -> User:
        s = socket.create_connection(self.channel, timeout=timeout)
        try:
            payload = request.serialize()
            path = b"/usersvc.UserService/GetUser"
            path = path.ljust(64, b"\x00")
            s.sendall(b"\x00" + struct.pack(">I", len(payload))
                      + path + payload)
            header = _recvn(s, 5)
            flag = header[0]
            length = struct.unpack(">I", header[1:5])[0]
            resp_data = _recvn(s, length)
            return User.deserialize(resp_data)
        finally:
            s.close()

    def ListUsers(self, timeout: float = 5.0):
        s = socket.create_connection(self.channel, timeout=timeout)
        try:
            path = b"/usersvc.UserService/ListUsers"
            path = path.ljust(64, b"\x00")
            s.sendall(b"\x00" + struct.pack(">I", 0) + path)
            while True:
                header = _recvn(s, 5)
                flag = header[0]
                length = struct.unpack(">I", header[1:5])[0]
                if flag == 0x02:  # end-of-stream
                    break
                data = _recvn(s, length)
                yield User.deserialize(data)
        finally:
            s.close()

def _recvn(conn, n: int) -> bytes:
    out = b""
    while len(out) < n:
        chunk = conn.recv(n - len(out))
        if not chunk:
            return out
        out += chunk
    return out

# --- Demo --------------------------------------------------------

def run_demo():
    print("=== gRPC mock demo (pure stdlib) ===\n")
    print("--- .proto source ---")
    print(PROTO)

    server = GRPCServer(host="127.0.0.1", port=50051)
    server.add_servicer(UserServiceServicer())
    t = threading.Thread(target=server.serve, daemon=True)
    t.start()
    time.sleep(0.2)
    print(f"[server] listening on 127.0.0.1:50051\n")

    stub = UserServiceStub(channel=("127.0.0.1", 50051))

    print("--- Unary RPC: GetUser(id=2) ---")
    resp = stub.GetUser(GetUserRequest(id=2))
    print(f"  response: id={resp.id} name={resp.name!r} "
          f"email={resp.email!r}")

    print("\n--- Unary RPC: GetUser(id=999) (not found) ---")
    resp = stub.GetUser(GetUserRequest(id=999))
    print(f"  response: id={resp.id} name={resp.name!r} "
          f"(server returns empty User for missing)")

    print("\n--- Server streaming RPC: ListUsers() ---")
    print("  receiving stream of User messages...")
    for i, u in enumerate(stub.ListUsers()):
        print(f"  msg {i+1}: id={u.id} name={u.name!r}")

    print("\n--- Wire format comparison: JSON vs Protobuf ---")
    user = User(id=42, name="Ada Lovelace", email="ada@example.com")
    pb = user.serialize()
    js = json.dumps({"id": 42, "name": "Ada Lovelace",
                     "email": "ada@example.com"}).encode()
    print(f"  Protobuf: {len(pb)} bytes  -> {pb!r}")
    print(f"  JSON:     {len(js)} bytes  -> {js!r}")
    print(f"  Protobuf is {len(js) - len(pb)} bytes smaller "
          f"({(1 - len(pb)/len(js)) * 100:.0f}% savings)")

    print("\n--- gRPC vs REST at a glance ---")
    print("  gRPC:  HTTP/2, binary (Protobuf), schema-required, "
          "4 RPC types, streaming")
    print("  REST:  HTTP/1.1 or HTTP/2, text (JSON), schema-optional, "
          "unary only")
    print("  gRPC:  best for internal service-to-service (Netflix, "
          "etcd, Kubernetes)")
    print("  REST:  best for public APIs (browser, mobile, "
          "third-party devs)")

if __name__ == "__main__":
    run_demo()
